pragma solidity ^0.8.0;

contract Sigil {

mapping(bytes32 => uint256) public charges;

event SigilCreated(bytes32 indexed sigilHash, string intention);

event SigilCharged(bytes32 indexed sigilHash, uint256 amount);

function createSigil(string memory intention) public returns (bytes32) {

bytes32 sigilHash = keccak256(abi.encodePacked(intention));

emit SigilCreated(sigilHash, intention);

return sigilHash;

}

function chargeSigil(bytes32 sigilHash) public payable {

require(msg.value > 0, "Must send energy");

charges[sigilHash] += msg.value;

emit SigilCharged(sigilHash, msg.value);

}

function getCharge(bytes32 sigilHash) public view returns (uint256) {

return charges[sigilHash];

}

}
